function imageTile(file,index,columns,rows,classes,label='',decorative=false){const col=index%columns,row=Math.floor(index/columns);return `<span class="image-tile ${classes}" ${decorative?'aria-hidden="true"':'role="img" aria-label="'+esc(label)+'"'}><img src="assets/${file}" alt="" loading="lazy" decoding="async" style="width:${columns*100}%;height:${rows*100}%;left:${-col*100}%;top:${-row*100}%"></span>`}

function icon(name){return imageTile('achievement-art.png',ICON_ART[name]??5,5,5,'icon image-icon','',true)}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
