function collectedProducts(s){return new Set(data.purchases.filter(p=>p.sid===s.id).map(p=>p.pid))}
function collectionProgress(s){const owned=collectedProducts(s);return `<section class="merch-collections card pad mb"><h2>Your St Peter’s merchandise collections</h2><p class="hint">Collect each item to complete a set. The shop records items when you collect them.</p><div class="collection-list">${merchandiseSets.map(set=>{const count=set.ids.filter(id=>owned.has(id)).length;return `<article><div class="between"><h3>${set.name}</h3><b>${count} / ${set.ids.length} collected</b></div><div class="progress"><span style="width:${count/set.ids.length*100}%"></span></div><ul>${set.ids.map(id=>{const p=products.find(p=>p.id===id);return `<li class="${owned.has(id)?'collected':''}">${icon(owned.has(id)?'check':'lock')} ${p.name}<span>${owned.has(id)?'Collected':p.price+' pts'}</span></li>`}).join('')}</ul>${count===set.ids.length?'<p class="collection-complete">Set complete!</p>':''}</article>`}).join('')}</div></section>`}

function guardian(tier=0){const t=tiers[tier];if(!t)return '';return `<div class="recognition-emblem" role="img" aria-label="${t.name} recognition artwork">${imageTile('recognition-owls.png',tier,4,1,'recognition-art',t.name+' collectible owl')}<span class="level-label">LEVEL ${tier+1}</span></div>`}
function art(type,value=''){const i=type==='stickers'?({Respect:7,Engagement:8,Aspiration:9,Leadership:10}[value]??7):({pencil:0,eraser:1,notebook:2,pencilcase:3,keyring:4,bottle:5,cap:6}[type]??11);return imageTile('merchandise-photos.png',i,4,3,'merch-photo','Illustrative St Peter’s merchandise photograph')}
function rewardArt(p){return `<div class="reward-art ${p.tone}">${art(p.art,p.value)}</div>`}
function initials(name){return name.split(' ').map(n=>n[0]).join('')}
const classes=['7A','7B','8A','8B','9A','9B','10A','10B'];
const teachingGroups=[['7SCI1','Science','7A'],['7ENG1','English','7A'],['8SCI1','Science','8A'],['8MAT1','Mathematics','8A'],['9SCI1','Science','9A'],['9ENG1','English','9A'],['9MAT1','Mathematics','9A'],['9PE1','PE','9A'],['9SCI2','Science','9B'],['10SCI1','Science','10A'],['10ART1','Arts','10A']].map(([id,subject,home])=>({id,subject,home}));
const first=['Alex','Mia','Noah','Aria','Leo','Isla','Theo','Zoe','Eli','Ruby','Finn','Ava'];
const last=['Morgan','Patel','Wilson','Chen','Williams','Taylor','Singh','Walker','Brown','Clarke','Scott','Reid'];
const colourPairs=[['#ece3f5','#9675b1'],['#e6eee8','#799c8a'],['#f6e9df','#b69580'],['#e5eaf6','#8e9fbe'],['#f4e2e9','#bb8c9f'],['#f5efdd','#b39d6e']];
// Expanded fictional history is appended once, including for existing demo sessions.
const DEMO_SUBJECTS=[
{name:'Science',code:'SCI',staff:['Ms Chen','Mr Taylor']},
{name:'English',code:'ENG',staff:['Ms Wilson','Mr Morgan']},
{name:'Mathematics',code:'MAT',staff:['Mr Patel','Ms Reid']},
{name:'PE',code:'PE',staff:['Ms Clarke','Mr Brown']},
{name:'Arts',code:'ART',staff:['Ms Walker','Mr Singh']}
];
function enrichDemoHistory(d){
 if(d.recognitionHistoryVersion===1)return false;
 const today=localDate(),anchor=Date.parse(today+'T00:00:00Z'),existing=new Set(d.awards.map(a=>a.id));
 const sessions=new Map();
 for(const a of d.awards){if(a.context!=='lesson')continue;let x=sessions.get(a.lesson);if(!x){x={regular:new Set(),stars:new Set()};sessions.set(a.lesson,x)}(a.star?x.stars:x.regular).add(a.sid)}
 const push=a=>{if(existing.has(a.id))return false;existing.add(a.id);d.awards.push(a);return true};
 const startCount=d.awards.length,cohorts=[...new Set(d.students.map(s=>s.cls))];
 d.students.forEach(s=>{s.demoSubjects=[...new Set([...(s.demoSubjects||[]),...DEMO_SUBJECTS.map(x=>x.name)])]});
 const messages={effort:['Kept working through a challenging task.','Stayed focused and completed careful work.','Showed sustained effort during independent practice.'],questions:['Shared a thoughtful explanation with the class.','Joined in positively and explained their reasoning.','Asked a useful question that helped learning.'],progress:['Acted on feedback and improved their work.','Corrected an error and explained the improvement.','Made a clear step forward in understanding.']};
 let lessonDays=0;
 for(let ago=42;ago>=1;ago--){
  const timestamp=anchor-ago*86400000,date=new Date(timestamp).toISOString().slice(0,10),weekday=new Date(timestamp).getUTCDay();
  if(weekday===0||weekday===6)continue;lessonDays++;
  cohorts.forEach((home,ci)=>{
   const roster=d.students.filter(s=>s.cls===home);
   for(let slot=0;slot<3;slot++){
    const subject=DEMO_SUBJECTS[(lessonDays+slot+ci)%DEMO_SUBJECTS.length],si=DEMO_SUBJECTS.indexOf(subject),period=String(slot+1),known=teachingGroups.find(g=>g.home===home&&g.subject===subject.name),groupId=known?.id||parseInt(home)+subject.code+(home.endsWith('A')?'1':'2'),lesson=groupId+'|'+date+'|'+period;
    const session=sessions.get(lesson)||{regular:new Set(),stars:new Set()};sessions.set(lesson,session);
    const reason=lessonCats[(lessonDays+ci+slot)%lessonCats.length],operator=subject.staff[(lessonDays+ci)%2],selected=[];
    roster.forEach(st=>{const sidNumber=Number(st.id.replace(/\D/g,''))||0;if(sidNumber%19===0)return;const hash=(sidNumber*31+ago*17+si*23+ci*13)%100,rate=28+(sidNumber%5)*9+si*2+(ago<15?12:0);if(hash>=rate)return;
     if(!session.regular.has(st.id)){push({id:'rich-history-v1|'+lesson+'|'+st.id+'|regular',sid:st.id,cat:reason.id,amount:1,star:false,context:'lesson',lesson,cls:groupId,subject:subject.name,date,period,location:'',note:messages[reason.id][(sidNumber+ago)%3],time:timestamp+slot*3600000,operator});session.regular.add(st.id)}
     selected.push(st);
    });
    if((lessonDays+ci+slot)%3===0){const targets=selected.filter(st=>!session.stars.has(st.id));const starSlots=Math.min(2-session.stars.size,(lessonDays+ci)%5===0?2:1);for(const st of targets.slice(0,starSlots)){push({id:'rich-history-v1|'+lesson+'|'+st.id+'|star',sid:st.id,cat:'star',amount:2,star:true,context:'lesson',lesson,cls:groupId,subject:subject.name,date,period,location:'',note:'An exceptional contribution to learning and a positive example to others.',time:timestamp+slot*3600000+600000,operator});session.stars.add(st.id)}}
   }
  });
 }
 const locations=['Library','School grounds','Dining hall','School event','Corridor','Other school setting'];
 const outsideNotes=['Included a student who was on their own.','Helped leave a shared space tidy and ready for others.','Participated positively in a lunchtime activity.','Made a useful contribution to a group activity.','Took on a new challenge outside their usual comfort zone.','Persevered when an activity became difficult.','Helped a younger student take part successfully.','Took responsibility and supported others without being asked.'];
 for(let ago=41;ago>=0;ago--){const timestamp=anchor-ago*86400000,date=new Date(timestamp).toISOString().slice(0,10);if([0,6].includes(new Date(timestamp).getUTCDay()))continue;
  d.students.forEach((st,i)=>{if(i%19===0||(i*7+ago*11)%13!==0)return;const ri=(i+ago)%outsideReasons.length,reason=outsideReasons[ri];push({id:'rich-history-v1|outside|'+date+'|'+st.id,sid:st.id,cat:reason.id,value:reason.value,amount:(i+ago)%3===0?2:1,star:false,context:'outside',lesson:'outside|'+date+'|sample-'+st.id,subject:'Beyond lessons',date,period:'',location:locations[(i+ago)%locations.length],note:outsideNotes[ri],time:timestamp+4*3600000,operator:['Pastoral team','Ms Wilson','Mr Patel','Ms Clarke'][(i+ago)%4]})})
 }
 d.recognitionHistoryVersion=1;d.recognitionHistory={from:new Date(anchor-42*86400000).toISOString().slice(0,10),to:today,lessonDays,awardsAdded:d.awards.length-startCount};return true;
}

function seed(){const d={version:2,students:[],awards:[],purchases:[],goals:{s48:'notebook'},stock:Object.fromEntries(products.map(p=>[p.id,p.stock])),created:Date.now()};classes.forEach((cls,c)=>{for(let i=0;i<12;i++){let total=18+((i*13+c*21)%143);const catBase=Object.fromEntries(cats.map((cat,k)=>[cat.id,Math.floor(total/5)+(k<total%5?1:0)]));d.students.push({id:`s${c*12+i}`,name:`${first[i]} ${last[(i+c*3)%12]}`,cls,year:parseInt(cls),base:total,spent:Math.floor(total/42)*10,starBase:0,catBase})}});d.students.find(s=>s.id==='s84').name='Luca Morgan';d.students.forEach((s,i)=>{if(i%7===0&&s.id!=='s84')return;for(let j=0;j<2;j++){const date=localDate(Date.now()-(2+j+(i%5))*86400000),group=teachingGroups.filter(g=>g.home===s.cls)[j%Math.max(1,teachingGroups.filter(g=>g.home===s.cls).length)];const outside=j===1&&i%3===0;const subject=group?.subject||'Science',cls=group?.id||`${s.year}SCI2`,cat=cats[(i+j)%cats.length].id;d.awards.push({id:`seed-${i}-${j}`,sid:s.id,cat,amount:outside?2:1,star:false,context:outside?'outside':'lesson',lesson:outside?`outside|${date}|seed-${i}`:`${cls}|${date}|${j+1}`,cls,subject:outside?'Beyond lessons':subject,date,period:String(j+1),location:outside?'School grounds':'',note:outside?'Helped another student feel included.':'Kept working after feedback and improved their work.',time:Date.now()-(2+j+(i%5))*86400000,operator:outside?'Pastoral team':subject==='English'?'Ms Wilson':subject==='Mathematics'?'Mr Patel':'Gary Talbot'})}});enrichDemoHistory(d);return d}
const KEY='stp-school-positives-v2';let data;let storageOK=true;try{data=JSON.parse(localStorage.getItem(KEY));if(!data||data.version!==2)data=seed()}catch{data=seed();storageOK=false}
let state={role:'student',page:'dashboard',student:'s48',cls:'9SCI1',date:new Date().toLocaleDateString('en-CA',{timeZone:'Pacific/Auckland'}),period:'1',selected:new Set(),reason:'effort',search:'',lessonNote:'',league:'class',leagueClass:'9A',leagueYear:9,leagueMeasure:'students',rewardFilter:'all',badgeFilter:'all',shopStudent:'s48',shopProduct:'notebook',shopSearch:'',lastUnlock:'',certYear:'9',certClass:'all',certStatus:'pending',certTier:'all',certSearch:'',certPreviewKeys:[],outsideSearch:'',outsideStudent:'',outsideReason:'teamwork',outsideAmount:'2',outsideLocation:'School grounds',outsideNote:'',outsideBusy:false,adminRole:'school',adminSubject:'Science',adminYear:'9',filterYear:'all',filterSubject:'all',filterContext:'all',filterFrom:'',filterTo:'',family:'morgan',parentChild:'s48'};
products.forEach(p=>{if(data.stock[p.id]===undefined)data.stock[p.id]=p.stock});
if(enrichDemoHistory(data))save();
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));storageOK=true}catch{storageOK=false;toast('Browser storage is unavailable. Demo changes last until this page closes.')}}
function student(id=state.student){return data.students.find(s=>s.id===id)}
function earned(s){return s.base+data.awards.filter(a=>a.sid===s.id).reduce((n,a)=>n+a.amount,0)}
function wallet(s){return earned(s)-s.spent-data.purchases.filter(p=>p.sid===s.id).reduce((n,p)=>n+p.price,0)}
function tierIndex(s){return tiers.reduce((n,t,i)=>earned(s)>=t.at?i:n,-1)}
function recognition(s){return tiers[tierIndex(s)]||{name:'Working towards Level 1',title:'Your first milestone is ahead',at:0,power:'Level 1 recognition unlocks at 100 lifetime points.'}}
function starCount(s){return s.starBase+data.awards.filter(a=>a.sid===s.id&&a.star).length}
function categoryCount(s,id){if(id==='star')return s.starBase*2+data.awards.filter(a=>a.sid===s.id&&a.star).reduce((n,a)=>n+a.amount,0);return (s.catBase[id]||0)+data.awards.filter(a=>a.sid===s.id&&a.cat===id).reduce((n,a)=>n+a.amount,0)}
function lessonKey(){return `${state.cls}|${state.date}|${state.period}`}
function lessonAwards(s){return data.awards.filter(a=>a.sid===s.id&&a.lesson===lessonKey())}
function lessonPoints(s){return lessonAwards(s).reduce((n,a)=>n+a.amount,0)}
function lessonStar(){return data.awards.filter(a=>a.lesson===lessonKey()&&a.star)}
function avatar(s,big=false){const c=colourPairs[Number(s.id.slice(1))%6];return `<span class="avatar ${big?'big':''}" style="background:${c[0]};color:${c[1]}">${initials(s.name)}</span>`}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
// Certificates are derived from lifetime points, so shop purchases never remove eligibility.
function certificatePoints(i){return tiers[i]?.at??null}
function certificateVenue(i){return i===tiers.length-1?'Celebration assembly':i===tiers.length-2?'Year assembly':'Class or tutor time'}
function certificateRows(){return data.students.flatMap(s=>tiers.flatMap((t,i)=>earned(s)>=certificatePoints(i)?[{key:s.id+'|'+(i+1)+'|'+certificatePoints(i),s,t,i,record:(data.certificates||{})[s.id+'|'+(i+1)+'|'+certificatePoints(i)]}]:[]))}
function filteredCertificates(){return certificateRows().filter(r=>(state.certYear==='all'||r.s.year===Number(state.certYear))&&(state.certClass==='all'||r.s.cls===state.certClass)&&(state.certStatus==='all'||(state.certStatus==='printed'?!!r.record:!r.record))&&(state.certTier==='all'||r.i===Number(state.certTier))&&(!state.certSearch||r.s.name.toLowerCase().includes(state.certSearch.toLowerCase()))).sort((a,b)=>a.s.cls.localeCompare(b.s.cls)||a.s.name.localeCompare(b.s.name)||a.i-b.i)}
function certificateOptions(values,current){return values.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(l)}</option>`).join('')}
function certificateCentre(){const rows=filteredCertificates(),pending=rows.filter(r=>!r.record);return heading('Milestone certificates.','Certificates appear automatically when students earn each recognition milestone.','<span class="chip">'+icon('award')+' Student leader tools</span>')+`<div class="card pad certificate-intro"><h2>Recognition that grows with the student</h2><p>Positive contributor (100 points) and Role model (250 points): class or tutor time. School champion (500 points): year assembly. Community ambassador (1,000 points): celebration assembly.</p><p class="hint">Certificates recognise 100, 250, 500 and 1,000 lifetime points. Level 1 starts at 100 lifetime points. Spending and printing leave lifetime points unchanged.</p></div><div class="certificate-filters card pad"><div class="field"><label for="cert-year">Year group</label><select id="cert-year" data-change="certYear">${certificateOptions([['all','All junior years'],...[7,8,9,10].map(y=>[y,'Year '+y])],state.certYear)}</select></div><div class="field"><label for="cert-class">Tutor group</label><select id="cert-class" data-change="certClass">${certificateOptions([['all','All classes'],...classes.map(c=>[c,c])],state.certClass)}</select></div><div class="field"><label for="cert-tier">Recognition level</label><select id="cert-tier" data-change="certTier">${certificateOptions([['all','All levels'],...tiers.map((t,i)=>[i,'Level '+(i+1)+' · '+t.name])],state.certTier)}</select></div><div class="field"><label for="cert-status">Print status</label><select id="cert-status" data-change="certStatus">${certificateOptions([['pending','Ready to print'],['printed','Printed'],['all','All certificates']],state.certStatus)}</select></div><div class="field"><label for="cert-search">Student name</label><input id="cert-search" data-change="certSearch" value="${esc(state.certSearch)}" placeholder="Find a student"></div></div><div class="section-head"><div><h2>${rows.length} certificates ${state.certStatus==='pending'?'ready to print':'in this view'}</h2><p class="sub">Year 9 illustrates the filters. No trial cohort or start date has been agreed.</p></div><button class="button" data-action="certBatch" ${pending.length?'':'disabled'}>${icon('award')} Prepare ${pending.length} pending certificates</button></div><p class="hint">Preview, print or save as PDF, then mark printed once printing succeeds. Cancelled prints remain ready. Printed certificates can be reprinted.</p><div class="card table-wrap"><table class="league-table"><thead><tr><th>Student</th><th>Milestone</th><th>Presentation</th><th>Status</th><th>Certificate</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.s.name)}</b><br><small>${r.s.cls} · ${earned(r.s)} lifetime points</small></td><td>${r.t.name}<br><small>${certificatePoints(r.i)} point${certificatePoints(r.i)===1?'':'s'}</small></td><td>${certificateVenue(r.i)}</td><td>${r.record?'Printed '+esc(r.record.date):'Ready to print'}</td><td><button class="button outline" data-action="certPreview" data-value="${r.key}">${r.record?'Preview / reprint':'Preview / print'}</button></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No certificates match these filters. Certificates appear here automatically as milestones are earned.</div></td></tr>'}</tbody></table></div><p class="hint">Prototype uses fictional students and records print status in this browser only. Assembly presentation follows school approval and arrangements.</p>`}
function certificateMarkup(r){const date=r.record?.date||new Date().toLocaleDateString('en-NZ',{timeZone:'Pacific/Auckland',day:'numeric',month:'long',year:'numeric'});return `<article class="milestone-certificate certificate-v2" style="--metal:${r.t.colour};--metal-light:${r.t.light}"><svg class="certificate-art" viewBox="0 0 1200 848" preserveAspectRatio="none" aria-hidden="true"><defs><pattern id="dots-${r.s.id}-${r.i}" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1.1" fill="#001834" opacity=".08"/></pattern><linearGradient id="metal-${r.s.id}-${r.i}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${r.t.light}"/><stop offset="1" stop-color="${r.t.colour}"/></linearGradient></defs><rect width="1200" height="848" fill="#fffdf6"/><rect width="278" height="848" fill="#061d35"/><path d="M0 0h278v848H0" fill="url(#dots-${r.s.id}-${r.i})"/><path d="M0 0h278v22H0" fill="#cc0033"/><path d="m278 0 24 0 0 848-24 0" fill="url(#metal-${r.s.id}-${r.i})"/><path d="M332 40h828v768H332" fill="none" stroke="${r.t.colour}" stroke-width="2"/><path d="M346 54h800v740H346" fill="none" stroke="${r.t.colour}" stroke-width=".7"/><path d="M1040 808h120V688" fill="none" stroke="${r.t.colour}" stroke-width="7"/><path d="M332 158V40h118" fill="none" stroke="${r.t.colour}" stroke-width="7"/></svg><div class="certificate-side-brand">ST PETER’S<span>RECOGNITION</span></div><div class="certificate-guardian">${guardian(r.i)}</div><div class="certificate-side-level">LEVEL ${r.i+1}<strong>${r.t.name.toUpperCase()}</strong><span>${r.t.title}</span></div><div class="certificate-topline">ST PETER’S</div><div class="certificate-seal"><b>${r.t.symbol}</b><span>${r.t.name}</span></div><div class="certificate-main"><div class="certificate-subject">CERTIFICATE OF ACHIEVEMENT</div><h2 class="certificate-title">${r.t.name} Award</h2><div class="certificate-small-rule"></div><p class="certificate-awarded">Proudly presented to</p><h3 class="certificate-name">${esc(r.s.name)}</h3><p class="certificate-class">YEAR ${r.s.year} · ${esc(r.s.cls)}</p><p class="certificate-message">For your hard work, curiosity and positive<br>contribution to our school.</p><div class="certificate-milestone">${certificatePoints(r.i).toLocaleString('en-NZ')} LIFETIME POSITIVE POINTS</div></div><div class="certificate-bottom"><div><b>St Peter’s</b><span>Issued ${esc(date)}</span></div><div><b>${certificateVenue(r.i)}</b><span>Certificate ${esc(r.s.id.toUpperCase())}-${r.t.symbol}</span></div></div><div class="certificate-demo">PROTOTYPE · FICTIONAL STUDENT</div></article>`}
function previewCertificates(keys){if(!['shop','teacher'].includes(state.role))return toast('Use the student leader account to print certificates.');const rows=certificateRows().filter(r=>keys.includes(r.key));if(!rows.length)return toast('No eligible certificates in this selection.');state.certPreviewKeys=rows.map(r=>r.key);modal(rows.length===1?'Certificate preview':rows.length+' certificate previews',`<p>Check names and presentation venues. Use Print / save PDF, then mark printed after successful printing.</p><div class="certificate-previews">${rows.map(certificateMarkup).join('')}</div>`,`<button class="button outline" data-action="printCertificates">Print / save PDF</button><button class="button" data-action="markCertificatesPrinted">Mark ${rows.length} printed</button>`);$('#dialog').classList.add('certificate-dialog')}
function printCertificates(){if(!['shop','teacher'].includes(state.role))return;const keys=state.certPreviewKeys||[],rows=certificateRows().filter(r=>keys.includes(r.key));if(!rows.length)return;$('#certificate-print-root').innerHTML=rows.map(certificateMarkup).join('');window.print()}
function markCertificatesPrinted(){if(!['shop','teacher'].includes(state.role))return;const keys=state.certPreviewKeys||[],rows=certificateRows().filter(r=>keys.includes(r.key));data.certificates=data.certificates||{};const date=new Date().toLocaleDateString('en-NZ',{timeZone:'Pacific/Auckland',day:'numeric',month:'long',year:'numeric'});rows.forEach(r=>{if(!data.certificates[r.key])data.certificates[r.key]={date,time:Date.now(),operator:'Student leader team'}});save();$('#dialog').close();render();toast(rows.length+' certificates recorded as printed. Points are unchanged.')}

const navByRole={student:[['dashboard','home','My dashboard'],['rewards','shop','Reward shop'],['achievements','bolt','My Collection'],['leagues','trophy','The leagues']],teacher:[['teacherDashboard','home','Staff dashboard'],['classroom','users','Award lesson points'],['outside','heart','Out-of-class positives'],['counter','shop','Cash in points'],['certificateCentre','award','Certificates'],['leagues','trophy','The leagues'],['guide','book','How it works']],shop:[['counter','shop','Shop counter'],['certificateCentre','award','Certificates'],['rewards','coin','Reward catalogue'],['guide','book','How it works']],admin:[['analytics','target','Recognition analysis'],['outside','heart','Out-of-class positives'],['guide','book','How it works']],parent:[['parentView','heart','My children’s positives'],['guide','book','How it works']]};
const pageNames={certificateCentre:'Certificates',dashboard:'My dashboard',rewards:'Reward shop',achievements:'My Collection',leagues:'The leagues',teacherDashboard:'Staff dashboard',classroom:'Award lesson points',counter:'Shop counter',guide:'How it works',outside:'Out-of-class positives',analytics:'Recognition analysis',parentView:'My children’s positives'};
function render(){const s=student(),labels={student:'Student view',teacher:'Staff view',shop:'Shop counter',admin:'Leader analysis',parent:'Parent view'},pages={dashboard,teacherDashboard,achievements,rewards,leagues,classroom,counter,certificateCentre,guide,outside,analytics,parentView};if(!navByRole[state.role].some(x=>x[0]===state.page)&&state.page!=='guide')state.page=navByRole[state.role][0][0];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">${icon('award')}</div><strong>Rewards &<br>Recognition<small>ST PETER’S</small></strong></div><div class="nav-label">${state.role==='parent'?'YOUR FAMILY':state.role==='student'?'YOUR PROGRESS':'RECOGNITION PROPOSAL'}</div><nav class="nav" aria-label="Main navigation">${navByRole[state.role].map(([id,ic,label])=>`<button class="${state.page===id?'active':''}" data-action="nav" data-value="${id}">${icon(ic)}${label}</button>`).join('')}</nav><div class="side-foot"><div class="side-note"><b>Everyday positives matter</b><p>Specific praise builds positive connections.</p><button class="text-button" data-action="guide">About this prototype</button></div><div class="side-user"><span class="avatar">${state.role==='student'?initials(s.name):state.role==='parent'?'FM':state.role==='admin'?'SL':'ST'}</span><div><b>${state.role==='student'?esc(s.name):labels[state.role]}</b><small>Fictional demo account</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Rewards & Recognition / <strong>${pageNames[state.page]}</strong></div><div class="top-actions"><span class="demo-pill">DEMO DATA</span><div class="role-switch" aria-label="Switch demo account">${Object.entries(labels).map(([r,l])=>`<button data-action="role" data-value="${r}" class="${state.role===r?'active':''}" aria-pressed="${state.role===r}">${l}</button>`).join('')}</div></div></header><div class="content">${pages[state.page]()}<div class="banner">${icon('info')}<span>Fictional prototype. Demo roles simulate access, with changes saved ${storageOK?'in this browser only':'temporarily'}. School sign-in and verified family links are required before live use.</span></div><div class="footer-text">ST PETER’S · REWARDS AND RECOGNITION · PROPOSAL</div></div></main></div>`}
function studentPicker(){return `<div class="account-picker"><label for="student-switch">Viewing student</label><select id="student-switch" data-change="student">${data.students.map(s=>`<option value="${s.id}" ${s.id===state.student?'selected':''}>${esc(s.name)} · ${s.cls}</option>`).join('')}</select></div>`}
function heading(title,sub,extra=''){return `<div class="heading"><div><div class="eyebrow">${state.role==='parent'?'FAMILY RECOGNITION':state.role==='admin'?'LEADER ANALYSIS':'ST PETER’S · PROPOSAL'}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${extra}</div>`}
function stats(items){return `<div class="stats">${items.map(([ic,label,value,sub])=>`<div class="card stat"><span class="stat-icon">${icon(ic)}</span><div><small>${label}</small><strong>${value}</strong><em>${sub}</em></div></div>`).join('')}</div>`}
function valueCount(s,value){return data.awards.filter(a=>a.sid===s.id&&a.context==='outside'&&(a.value||outsideReasons.find(r=>r.id===a.cat)?.value)===value).length}
function getBadges(s){return [
{name:'First spark',desc:'Earn your first positive point.',ic:'bolt',count:earned(s),goal:1,tone:'purple'},
{name:'Curious thinker',desc:'Earn 15 points for focus and participation.',ic:'question',count:categoryCount(s,'questions'),goal:15,tone:'purple'},
{name:'Helping hand',desc:'Earn 15 points for helping others.',ic:'heart',count:categoryCount(s,'teamwork'),goal:15,tone:'green'},
{name:'Effort champion',desc:'Earn 25 points for excellent effort.',ic:'bolt',count:categoryCount(s,'effort'),goal:25,tone:''},
{name:'Feedback in action',desc:'Earn 20 points for progress and acting on feedback.',ic:'target',count:categoryCount(s,'progress')+categoryCount(s,'practical'),goal:20,tone:'green'},
{name:'Rising star',desc:'Be Star of the Lesson 3 times.',ic:'star',count:starCount(s),goal:3,tone:''},
{name:'Shining example',desc:'Be Star of the Lesson 10 times.',ic:'star',count:starCount(s),goal:10,tone:'purple'},
{name:'Progress maker',desc:'Earn 20 points for great progress.',ic:'target',count:categoryCount(s,'progress'),goal:20,tone:'green'},
{name:'Positive century',desc:'Reach 100 lifetime points.',ic:'trophy',count:earned(s),goal:100,tone:''},
{name:'All-round contributor',desc:'Earn at least 10 points in each lesson category.',ic:'award',count:Math.min(...lessonCats.map(c=>categoryCount(s,c.id))),goal:10,tone:'purple'},
{name:'Community spirit',desc:'Receive out-of-class recognition on 3 occasions.',ic:'users',count:data.awards.filter(a=>a.sid===s.id&&a.context==='outside').length,goal:3,tone:'green'},
{name:'Reward unlocked',desc:'Collect your first reward at the shop.',ic:'shop',count:data.purchases.filter(p=>p.sid===s.id).length,goal:1,tone:'green'},...schoolValues.map((value,i)=>({name:value+' in action',desc:'Receive recognition for '+value.toLowerCase()+' on 3 occasions outside lessons.',ic:['heart','users','target','award'][i],count:valueCount(s,value),goal:3,tone:i%2?'purple':'green',value}))]}
function badgeToken(b){return `<div class="badge-token achievement-art ${b.tone}">${imageTile('achievement-art.png',ACHIEVEMENT_ART[b.name]??ICON_ART[b.ic]??0,5,5,'achievement-picture',b.name+' digital achievement artwork')}</div>`}
function dashboard(){const s=student(),ti=tierIndex(s),t=recognition(s),next=tiers[ti+1],goal=products.find(p=>p.id===data.goals[s.id]),badges=getBadges(s),unlocked=badges.filter(b=>b.count>=b.goal),rank=data.students.filter(x=>x.cls===s.cls).sort((a,b)=>earned(b)-earned(a)||a.name.localeCompare(b.name)).findIndex(x=>x.id===s.id)+1;
return heading(`Hi ${esc(s.name.split(' ')[0])}, your positives add up.`,"Every bit of effort adds up. Here’s where your school journey stands.",studentPicker())+`<div class="grid2"><div><div class="hero"><div class="hero-text"><div class="eyebrow">${ti<0?'WORKING TOWARDS LEVEL 1':t.name.toUpperCase()+' RECOGNITION · LEVEL '+(ti+1)}</div><h2>${t.title}</h2><p>${t.power} ${next?`${next.at-earned(s)} more points to reach ${next.name}.`:'You have reached our highest recognition level.'}</p><button class="button" data-action="nav" data-value="achievements">View My Collection</button></div>${guardian(ti)}<span class="hero-spark">✧</span><span class="hero-star">✦</span></div>${stats([['coin','Ready to spend',wallet(s),'Your reward shop balance'],['star','Lifetime points',earned(s),'Every positive point counts'],['award','Achievements unlocked',unlocked.length+'<span style="font-size:13px;color:#b0a3ba;letter-spacing:0"> / '+badges.length+'</span>','Your achievements, forever']])}<div class="card pad mb"><div class="section-head"><h2>Your positive moments</h2><span class="chip">${s.cls} · Participating groups</span></div>${activity(s,5)}</div><div class="card pad"><div class="section-head"><h2>What makes you shine</h2><span class="sub">Points by category</span></div>${breakdown(s)}</div></div><div class="stack"><div class="card pad"><div class="section-head"><h2>Your next milestone</h2>${icon('target')}</div><div class="level-row">${guardian(next?ti+1:ti)}<div class="level-detail"><h3>${next?next.name:'Collection complete'}</h3><span class="sub">${next?'Level '+(ti+2)+' · '+next.at+' lifetime points':'Community ambassador · Level 4'}</span></div></div><div class="between progress-label"><span>${earned(s)} lifetime points</span><span>${next?next.at:'1,000+'}</span></div><div class="progress"><span style="width:${next?Math.min(100,(earned(s)-t.at)/(next.at-t.at)*100):100}%"></span></div><p class="hint">${next?`Only ${next.at-earned(s)} points to go. Your level stays yours, even when you spend points.`:'All four levels unlocked. Spending never removes them.'}</p><div class="reward-tiny">${goal?rewardArt(goal):'<div class="stat-icon">'+icon('shop')+'</div>'}<div><h4>${goal?'Saving for '+goal.name:'Choose your next reward'}</h4><small>${goal?`${wallet(s)} / ${goal.price} points · ${wallet(s)>=goal.price?'Ready to collect!':(goal.price-wallet(s))+' more to go'}`:'Pick something you would love to earn.'}</small><br><button class="text-button" data-action="nav" data-value="rewards">Visit the reward shop</button></div></div></div><div class="card pad"><div class="section-head"><h2>Your digital achievements</h2><button class="text-button" data-action="nav" data-value="achievements">View all</button></div><div class="mini-badges">${unlocked.slice(0,3).map(b=>`<div>${badgeToken(b)}<strong>${b.name}</strong><small>Unlocked</small></div>`).join('')}</div></div><div class="card pad"><div class="section-head"><h2>Your class league</h2><span class="chip">Top 3 in ${s.cls}</span></div>${data.students.filter(x=>x.cls===s.cls).sort((a,b)=>earned(b)-earned(a)||a.name.localeCompare(b.name)).slice(0,3).map((x,i)=>`<div class="mini-ranking"><span class="rank-num">0${i+1}</span>${avatar(x)}<strong>${esc(x.name)}${x.id===s.id?' · You':''}</strong><span class="points">${earned(x)} pts</span></div>`).join('')}<button class="text-button mt" data-action="nav" data-value="leagues">Explore the leagues </button></div></div></div>`}
function breakdown(s){let allCats=[...cats,{id:'star',name:'Star of the Lesson',icon:'star'}];let max=Math.max(...allCats.map(c=>categoryCount(s,c.id)),1);return `<div class="category-breakdown">${allCats.map(c=>`<div class="category-row"><span>${icon(c.icon)} ${c.name}</span><div class="progress"><span style="width:${categoryCount(s,c.id)/max*100}%"></span></div><b>${categoryCount(s,c.id)}</b></div>`).join('')}</div>`}
function activity(s,limit=8,positiveOnly=false){const rows=[...data.awards.filter(a=>a.sid===s.id).map(a=>({...a,type:'award'})),...(positiveOnly?[]:data.purchases.filter(p=>p.sid===s.id).map(p=>({...p,type:'purchase'})))].sort((a,b)=>b.time-a.time);return rows.slice(0,limit).map(a=>{const c=allReasons.find(c=>c.id===a.cat),purchase=a.type==='purchase',title=purchase?products.find(p=>p.id===a.pid).name+' collected':a.star?'Star of the Lesson':c?.name||'Positive contribution';return `<div class="activity-row"><span class="activity-icon">${icon(purchase?'shop':a.star?'star':c?.icon||'heart')}</span><div><h4>${title}</h4><small>${purchase?'School shop':a.context==='outside'?esc(a.location)+' · Out of class':esc(a.subject)+' · Period '+a.period} · ${when(a.time)}</small>${a.note?`<p>${esc(a.note)}</p>`:''}${!purchase?`<small>Recognised by ${esc(a.operator)}</small>`:''}</div><span class="delta ${purchase?'spend':''}">${purchase?'−'+a.price:'+'+a.amount} pts</span></div>`}).join('')||'<p class="empty">No positive moments recorded yet.</p>'}
function when(time){return new Date(time).toLocaleDateString('en-NZ',{day:'numeric',month:'short',timeZone:'Pacific/Auckland'})}
function achievements(){let s=student(),ti=tierIndex(s),badges=getBadges(s),earnedBadges=badges.filter(b=>b.count>=b.goal),shown=badges.filter(b=>state.badgeFilter==='all'||(state.badgeFilter==='unlocked'?b.count>=b.goal:b.count<b.goal));return heading('My Collection','Unlock digital achievements for learning, positive contributions and our REAL values.',studentPicker())+`<div class="section-head"><h2>Recognition levels</h2><span class="sub">${ti+1} of ${tiers.length} unlocked · based on lifetime points</span></div><div class="guardians">${tiers.map((t,i)=>`<div class="guardian-card ${i>ti?'locked':''} ${i===ti?'current':''}">${guardian(i)}<h3>${t.name}</h3><p>Level ${i+1} · ${t.at} points</p><p class="certificate-venue">${'Certificate at '+certificatePoints(i).toLocaleString('en-NZ')+' lifetime points · '+certificateVenue(i)}</p><span class="status">${i>ti?icon('lock')+' '+(t.at-earned(s))+' points to go':i===ti?'YOUR CURRENT LEVEL':'✓ COLLECTED'}</span></div>`).join('')}</div><div class="section-head"><h2>Digital achievements <span class="sub">${earnedBadges.length} / ${badges.length}</span></h2><div class="tabs">${[['all','All achievements'],['unlocked','Unlocked'],['locked','To discover']].map(([v,l])=>`<button class="${state.badgeFilter===v?'active':''}" data-action="badgeFilter" data-value="${v}">${l}</button>`).join('')}</div></div><div class="badge-grid">${shown.map(b=>`<div class="card achievement ${b.count<b.goal?'locked':''}">${badgeToken(b)}<h3>${b.name}</h3><p>${b.desc}</p>${b.count>=b.goal?'<span class="earned">'+icon('check')+' Unlocked — yours to keep</span>':`<div class="between progress-label"><span>Keep going</span><span>${Math.min(b.count,b.goal)} / ${b.goal}</span></div><div class="progress"><span style="width:${Math.min(100,b.count/b.goal*100)}%"></span></div>`}</div>`).join('')||'<div class="empty">All caught up! Every achievement in this collection is unlocked.</div>'}</div><p class="hint">Recognition levels and achievements unlock automatically. Shop purchases never remove your level or earned achievements.</p>`}
function rewards(){const s=student(),isStudent=state.role==='student',balance=wallet(s),shown=products.filter(p=>state.rewardFilter==='all'||(state.rewardFilter==='affordable'?p.price<=balance:p.price>balance));return heading('St Peter’s merchandise collections.',isStudent?'Spend a little or save for something bigger. Your next milestone is up to you.':'Illustrative St Peter’s merchandise and point prices.',isStudent?`<span class="chip">${icon('coin')} ${balance} points to spend</span>`:'<span class="chip">Illustrative merchandise</span>')+`<div class="league-hero"><span>${icon('shop')}</span><div><h3>Merchandise to collect and save for.</h3><p>These St Peter’s merchandise images are illustrative concepts for possible rewards. Set a goal, then collect items through a supervised shop if the proposal progresses. Prices and availability are examples.</p></div></div>${isStudent?`<div class="toolbar"><div class="tabs">${[['all','All rewards'],['affordable','I can afford'],['saving','Save for later']].map(([v,l])=>`<button data-action="rewardFilter" data-value="${v}" class="${state.rewardFilter===v?'active':''}">${l}</button>`).join('')}</div><span class="spacer"></span><span class="sub">Your achievements &amp; levels are yours to keep.</span></div>`:''}${isStudent?collectionProgress(s):''}<div class="reward-grid">${shown.map(p=>{const goal=data.goals[s.id]===p.id,stock=data.stock[p.id];return `<article class="card reward-card"><div class="reward-art ${p.tone}"><span class="reward-category">${p.type.toUpperCase()}</span>${art(p.art,p.value)}${p.value?'<span class="merch-value">'+p.value+'</span>':''}</div><div class="reward-body"><div class="between"><h3>${p.name}</h3>${goal&&isStudent?'<span class="goal-tag">MY GOAL</span>':''}</div><p>${p.desc}</p><div class="between"><span class="points">${icon('coin')}${p.price} points</span><span class="stock">${stock>0?stock+' in the shop':'Out of stock'}</span></div>${isStudent?`<button class="button ${goal?'soft':'outline'}" data-action="goal" data-value="${p.id}" ${stock===0?'disabled':''}>${goal?icon('check')+' Saving for this':balance>=p.price?'Set goal · ready to collect':'Set as my savings goal'}</button>`:`<button class="button outline" data-action="${state.role==='shop'?'shopPick':'prizeInfo'}" data-value="${p.id}">${state.role==='shop'?'Redeem at the counter':'View reward'}</button>`}</div></article>`}).join('')||'<div class="empty">No rewards in this view. Try All rewards.</div>'}</div>`}
function classroom(){const group=lessonGroup(),roster=rosterForLesson(),visible=roster.filter(s=>s.name.toLowerCase().includes(state.search.toLowerCase())),awards=data.awards.filter(a=>a.lesson===lessonKey()),stars=lessonStar(),selected=roster.filter(s=>state.selected.has(s.id)),eligible=selected.filter(s=>!lessonAwards(s).some(a=>!a.star)),canStar=selected.length>0&&selected.length<=2-stars.length&&selected.every(s=>!lessonAwards(s).some(a=>a.star));return heading('Recognise a positive lesson.','One regular point per student, plus two extra for a lesson star.','<button class="button outline" data-action="nav" data-value="outside">Out-of-class recognition</button>')+`<div class="card pad mb"><div class="filters"><div class="field"><label for="class">Teaching group</label><select id="class" data-change="cls">${teachingGroups.map(g=>`<option value="${g.id}" ${g.id===state.cls?'selected':''}>${g.id} · ${g.subject}</option>`).join('')}</select></div><div class="field"><label for="lesson-date">Lesson date</label><input id="lesson-date" type="date" value="${state.date}" data-change="date" required></div><div class="field"><label for="period">Period</label><select id="period" data-change="period">${[1,2,3,4,5,6,7].map(p=>`<option ${String(p)===state.period?'selected':''}>${p}</option>`).join('')}</select></div><span class="chip">1 regular + 2 star = maximum 3</span></div></div><div class="summary-strip"><span><b>${roster.length}</b> students</span><span><b>${awards.reduce((n,a)=>n+a.amount,0)}</b> points this lesson</span><span><b>${stars.length} / 2</b> lesson stars awarded</span></div><div class="grid2 teacher"><div class="card pad"><div class="section-head"><h2>${state.cls} <span class="sub">${group.subject}</span></h2><input type="search" placeholder="Find a student" aria-label="Find a student in class" value="${esc(state.search)}" data-input="rosterSearch"></div><div class="toolbar"><b>${selected.length} selected</b><button class="text-button" data-action="selectAll">Select whole class</button><button class="text-button" data-action="clear">Clear</button></div><div class="roster">${visible.map(s=>`<button class="student-card ${state.selected.has(s.id)?'selected':''}" data-action="selectStudent" data-value="${s.id}" aria-pressed="${state.selected.has(s.id)}">${lessonAwards(s).some(a=>a.star)?'<span class="star-mark">★</span>':''}${avatar(s)}<strong>${esc(s.name)}</strong><small>${s.cls} · ${lessonPoints(s)} / 3 lesson points</small><small>${lessonAwards(s).some(a=>!a.star)?'Regular point awarded':'Regular point available'}</small></button>`).join('')||'<p class="empty">No matching students.</p>'}</div><h2 class="mt">Lesson activity</h2>${awards.slice().reverse().map(a=>`<div class="activity-row"><span class="activity-icon">${icon(a.star?'star':allReasons.find(c=>c.id===a.cat).icon)}</span><div><h4>${esc(student(a.sid).name)}</h4><small>${a.star?'Star of the Lesson':allReasons.find(c=>c.id===a.cat).name} · +${a.amount} points</small></div><button class="text-button" data-action="undoAward" data-value="${a.id}">Undo</button></div>`).join('')||'<p class="hint">Awards for this lesson appear here.</p>'}</div><aside class="card pad award-panel"><h2>Regular lesson point</h2><p>Choose one reason for everyone selected.</p><div class="reason-list">${lessonCats.map(c=>`<button class="reason ${state.reason===c.id?'active':''}" data-action="reason" data-value="${c.id}" aria-pressed="${state.reason===c.id}">${icon(c.icon)}${c.name}</button>`).join('')}</div><label for="lesson-note">Personal praise (optional)</label><textarea id="lesson-note" data-input="lessonNote" rows="2" maxlength="180" placeholder="One message for the selected students">${esc(state.lessonNote)}</textarea><p class="hint">One reason and message apply to everyone selected. Personal praise can also happen in conversation.</p><button class="button" data-action="award" ${eligible.length?'':'disabled'}>Award ${eligible.length||''} student${eligible.length===1?'':'s'} +1</button><p class="hint">One regular point per student per lesson. Students who already have it are skipped.</p><div class="star-box"><h3>${icon('star')} Star of the Lesson</h3><p><b>Two extra points</b> for each selected star. A maximum of <b>two students per lesson</b> can receive a star.</p><button class="button" data-action="star" ${canStar?'':'disabled'}>Award Star of the Lesson +2</button><p>${2-stars.length} star place${2-stars.length===1?'':'s'} left. Select one or two eligible students.</p></div></aside></div>`}
function award(star=false){if(state.role!=='teacher')return toast('Use the staff demo to award lesson points.');if(!state.date||!lessonGroup())return toast('Choose a valid lesson.');const roster=rosterForLesson(),chosen=[...state.selected].map(id=>roster.find(s=>s.id===id)).filter(Boolean);if(!chosen.length)return toast('Select a student in this teaching group.');if(star&&(chosen.length>2-lessonStar().length||chosen.some(s=>lessonAwards(s).some(a=>a.star))))return toast('A lesson can have at most two different stars. Each student can receive one star.');if(!lessonCats.some(c=>c.id===state.reason))return toast('Choose a lesson reason.');let affected=0,skip=0;for(const s of chosen){if(!star&&lessonAwards(s).some(a=>!a.star)){skip++;continue;}data.awards.push({id:uid(),sid:s.id,cat:star?'star':state.reason,amount:star?2:1,star,context:'lesson',lesson:lessonKey(),cls:state.cls,subject:lessonGroup().subject,date:state.date,period:state.period,time:Date.now(),operator:'Gary Talbot',note:state.lessonNote.trim()||(star?'An outstanding positive contribution to the lesson.':'')});affected++;}save();state.selected.clear();state.lessonNote='';render();toast(`${affected} student${affected===1?'':'s'} received ${star?'Star of the Lesson (+2 extra points)':'a regular lesson point (+1)'}.${skip?' '+skip+' already had their regular point.':''}`)}
function leagues(){const s=student(),scope=state.league;let pool=scope==='class'?data.students.filter(x=>x.cls===(state.role==='student'?s.cls:state.leagueClass)):scope==='year'?data.students.filter(x=>x.year===(state.role==='student'?s.year:state.leagueYear)):data.students;const aggregate=scope!=='class'&&state.leagueMeasure==='classes';let rows=aggregate?[...new Set(pool.map(x=>x.cls))].map(cls=>{const group=pool.filter(x=>x.cls===cls),total=group.reduce((n,x)=>n+earned(x),0);return {id:cls,name:cls,cls,year:group[0].year,total,avg:total/group.length,count:group.length,stars:group.reduce((n,x)=>n+starCount(x),0)}}):pool.map(x=>({...x,total:earned(x),stars:starCount(x)}));rows.sort((a,b)=>(aggregate?b.avg-a.avg:b.total-a.total)||a.name.localeCompare(b.name));const limit=scope==='class'?3:20;rows=rows.slice(0,limit);return heading('A little friendly competition.','Celebrate the effort across your class, your year and your school community.','<span class="chip">'+icon('trophy')+' Lifetime points · all time</span>')+`<div class="toolbar"><div class="tabs">${[['class','My class'],['year','Year group'],['school','Overall']].map(([v,l])=>`<button class="${scope===v?'active':''}" data-action="league" data-value="${v}">${l}</button>`).join('')}</div><span class="spacer"></span>${scope!=='class'?`<select aria-label="League table type" data-change="leagueMeasure"><option value="students" ${!aggregate?'selected':''}>Student league</option><option value="classes" ${aggregate?'selected':''}>Class league</option></select>`:''}${state.role!=='student'&&scope==='class'?`<select aria-label="League class" data-change="leagueClass">${classes.map(c=>`<option ${c===state.leagueClass?'selected':''}>${c}</option>`).join('')}</select>`:''}${state.role!=='student'&&scope==='year'?`<select aria-label="League year group" data-change="leagueYear">${[7,8,9,10].map(y=>`<option value="${y}" ${y===state.leagueYear?'selected':''}>Year ${y}</option>`).join('')}</select>`:''}</div><div class="league-hero"><span>${icon('trophy')}</span><div><h3>${scope==='class'?(state.role==='student'?s.cls:state.leagueClass):scope==='year'?'Year '+(state.role==='student'?s.year:state.leagueYear):'Overall leaders'}</h3><p>Only the top ${limit} ${aggregate?'classes':'students'} appear here. ${aggregate?'Classes rank by average lifetime points per student, so larger classes have no advantage.':'Every positive point adds to your place. Spending in the shop doesn’t change your ranking.'}</p></div></div><div class="card pad"><div class="section-head"><h2>${aggregate?'Class standings':'Student standings'}</h2><span class="sub">${rows.length} ${aggregate?'classes':'students'} · Years ${scope==='school'?'7–10':scope==='year'?(state.role==='student'?s.year:state.leagueYear):(state.role==='student'?s.year:parseInt(state.leagueClass))}</span></div><div class="table-wrap"><table class="league-table"><thead><tr><th>Rank</th><th>${aggregate?'Class':'Student'}</th><th>${aggregate?'Students':'Class'}</th><th>Stars</th><th>${aggregate?'Avg points':'Lifetime points'}</th></tr></thead><tbody>${rows.map((x,i)=>`<tr class="${(aggregate?x.cls===s.cls:x.id===s.id)&&state.role==='student'?'me':''}"><td>${i<3?`<span class="rank-medal ${i===1?'silver':i===2?'bronze':''}">${i+1}</span>`:`<span class="muted">${i+1}</span>`}</td><td><div class="league-name">${aggregate?'<span class="avatar">'+x.year+'</span>':avatar(x)}<b>${esc(x.name)}</b>${(aggregate?x.cls===s.cls:x.id===s.id)&&state.role==='student'?'<span class="you">'+(aggregate?'YOUR CLASS':'YOU')+'</span>':''}</div></td><td class="muted">${aggregate?x.count:x.cls}</td><td class="muted">☆ ${x.stars}</td><td><b style="color:#7c5c9e">${aggregate?x.avg.toFixed(1):x.total}</b> <span class="muted" style="font-size:9px">pts</span></td></tr>`).join('')}</tbody></table></div><p class="hint">Ties are ordered alphabetically. All scores are fictional demo data. Leagues count earned points, never unspent balances.</p></div>`}
function counter(){let s=student(state.shopStudent),p=products.find(p=>p.id===state.shopProduct),bal=wallet(s),can=bal>=p.price&&data.stock[p.id]>0;return heading('Cash in a student’s points.','Choose the student and their prize. Confirm the collection to deduct points from their account.','<span class="chip">'+icon('lock')+' '+(state.role==='teacher'?'Teacher shop access':'Shop operator demo')+'</span>')+`<div class="staff-links-strip"><button class="button outline" data-action="nav" data-value="certificateCentre">${icon('award')} Certificates</button>${state.role==='teacher'?'<button class="button outline" data-action="nav" data-value="teacherDashboard">Teacher dashboard</button>':''}<span class="chip">${icon('info')} The deduction applies only to the selected student</span></div><div class="shop-layout"><div class="card pad"><h2>1. Find the student</h2><p class="hint">Ask the student for their name and tutor group.</p><div class="field"><label for="counter-student">STUDENT &amp; CLASS</label><select id="counter-student" data-change="shopStudent">${data.students.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${esc(x.name)} · ${x.cls}</option>`).join('')}</select></div><div class="student-summary">${avatar(s,true)}<div><h3>${esc(s.name)}</h3><span class="sub">${s.cls} · ${recognition(s).name}</span></div><div class="wallet"><strong>${bal}</strong><small>points available</small></div></div><div class="section-head"><h2>2. Choose their reward</h2></div><div class="product-list">${products.map(x=>`<button class="product-pick ${p.id===x.id?'active':''}" data-action="counterProduct" data-value="${x.id}" aria-pressed="${p.id===x.id}">${rewardArt(x)}<div><h4>${x.name}</h4><small>${data.stock[x.id]} in stock</small></div><span class="points">${x.price} pts</span></button>`).join('')}</div><div class="checkout"><div class="between"><span>Available balance</span><b>${bal} pts</b></div><div class="between"><span>${p.name}</span><b>−${p.price} pts</b></div><div class="between" style="padding-top:12px;border-top:1px solid #e9dfef"><span>Balance after collection</span><b>${Math.max(0,bal-p.price)} pts</b></div>${!can?`<p>${bal<p.price?'Not enough points yet — '+(p.price-bal)+' more needed.':'This reward is out of stock.'}</p>`:'<p>Points are deducted only after you confirm. Their lifetime points and achievements stay unchanged.</p>'}<button class="button" data-action="checkout" ${can?'':'disabled'}>${icon('check')} Review &amp; confirm collection</button></div></div><div class="stack"><div class="card pad"><div class="section-head"><h2>Recent shop collections</h2><span class="sub">${data.purchases.length} total</span></div>${data.purchases.length?data.purchases.slice().reverse().slice(0,10).map(x=>`<div class="history-row"><div class="between"><h4>${esc(student(x.sid).name)}</h4><b class="points">−${x.price} pts</b></div><p>${products.find(p=>p.id===x.pid).name} · ${student(x.sid).cls} · ${when(x.time)}</p><div class="between"><span class="sub" style="font-size:10px">Balance after: ${x.after} pts · Shop team</span><button class="text-button" data-action="refund" data-value="${x.id}">Reverse collection</button></div></div>`).join(''):'<div class="empty">No prizes collected yet.<br>Complete a demo collection to see the audit trail here.</div>'}</div><div class="card pad"><h2>At the counter</h2><div class="rule"><span class="rule-num">1</span><div><h4>Check the right student</h4><p>Match both the student’s name and class.</p></div></div><div class="rule"><span class="rule-num">2</span><div><h4>Check the prize together</h4><p>Read the points cost and remaining balance.</p></div></div><div class="rule"><span class="rule-num">3</span><div><h4>Confirm, then hand it over</h4><p>The deduction and stock change happen together. A mistaken collection can be reversed.</p></div></div></div></div></div>`}
function modal(title,body,actions=''){let d=$('#dialog');d.classList.remove('certificate-dialog');d.innerHTML=`<div class="modal"><div class="modal-top"><h2>${title}</h2><button class="close" data-action="close" aria-label="Close dialog">✕</button></div>${body}${actions?'<div class="modal-actions">'+actions+'</div>':''}</div>`;d.showModal()}
function checkoutModal(){const s=student(state.shopStudent),p=products.find(p=>p.id===state.shopProduct);if(wallet(s)<p.price||data.stock[p.id]<1)return toast('Please check the balance and stock.');modal('Confirm their collection',`<p>You’re collecting this reward for <b>${esc(s.name)} · ${s.cls}</b>.</p>${rewardArt(p)}<div class="between"><b>${p.name}</b><span class="points">${p.price} points</span></div><p>Balance: <b>${wallet(s)} → ${wallet(s)-p.price} points</b><br>Lifetime points: <b>${earned(s)} — unchanged</b></p><p>Hand over the prize after confirming the collection.</p>`,'<button class="button outline" data-action="close">Go back</button><button class="button" data-action="confirmCheckout">Confirm collection</button>')}
function confirmCheckout(){let s=student(state.shopStudent),p=products.find(p=>p.id===state.shopProduct),before=wallet(s);if(before<p.price||data.stock[p.id]<1){$('#dialog').close();render();return toast('Balance or stock changed. Please check again.')}let unlockBefore=getBadges(s).filter(b=>b.count>=b.goal).length;data.purchases.push({id:uid(),sid:s.id,pid:p.id,price:p.price,before,after:before-p.price,time:Date.now(),operator:'Shop team'});data.stock[p.id]--;if(data.goals[s.id]===p.id)delete data.goals[s.id];save();$('#dialog').close();render();let unlocked=getBadges(s).filter(b=>b.count>=b.goal).length>unlockBefore;modal('Reward collected!',`<div class="center"><div class="success-seal">${icon('check')}</div><h3>${esc(s.name.split(' ')[0])} earned this.</h3><p>${p.name} · ${p.price} points spent<br><b>${wallet(s)} points left to save or spend</b></p>${unlocked?'<span class="chip">'+icon('award')+' Achievement unlocked: Reward unlocked!</span>':''}<p>Please hand over the prize now.</p></div>`,'<button class="button full" data-action="close">Ready for the next student</button>')}
function guide(){return heading('Rewards and recognition proposal.','A prototype to explore how everyday recognition could strengthen relationships.','<a class="button" href="'+SURVEY_URL+'" target="_blank" rel="noopener">Faculty and pastoral feedback</a>')+`<section class="card pad mb"><h2>Enhancing relationship-based pedagogy</h2><p>Help staff notice effort and progress, offer specific personal praise and follow up with encouragement. A positive record gives students and whānau successes to revisit together.</p><p>For a class, select students together, choose one of three broad learning reasons and award in a single action. Deselect students where appropriate. A personal message is optional.</p></section><div class="settings-grid"><section class="card pad"><h2>Leader feedback comes first</h2><p>Feedback from Heads of Faculty and pastoral leaders will guide whether this proposal progresses. If there is support, we can work through practical concerns and form a working party.</p><p><a href="${SURVEY_URL}" target="_blank" rel="noopener">Share positives, concerns and suggestions in the faculty and pastoral survey</a></p></section><section class="card pad"><h2>Development before a small trial</h2><p>The working party would agree behaviours to recognise, achievements, rewards and how the system should work. We would then build and test the working site before a small trial in a few departments.</p><p><b>A trial will not start immediately at the beginning of Term 1.</b> Timing depends on leader feedback, preparation and readiness.</p></section><section class="card pad"><h2>Three quick lesson reasons</h2><p><b>Effort</b>, <b>Focus and participation</b>, and <b>Progress and feedback</b>. Choose one reason for everyone selected.</p><p>One regular point per student per lesson. Star of the Lesson adds two extra points, for up to two students per lesson.</p></section><section class="card pad"><h2>Our REAL values beyond lessons</h2><p>Eight out-of-class choices sit under Respect, Engagement, Aspiration and Leadership. Add a short personal message and recognise a distinct event with 1 or 2 points.</p><p><a href="https://www.stpeters.school.nz/our-vision" target="_blank" rel="noopener">Values on the St Peter’s website</a>. The behaviour links are examples for a working party to refine.</p></section><section class="card pad"><h2>Achievements, milestones and certificates</h2><p>Achievements are digital collectibles for learning, positive contributions and our REAL values. They do not change points or award limits. Certificates start at 100 lifetime points, with further milestones at 250, 500 and 1,000. Recognition levels start at Level 1 (100 points). Shop spending leaves lifetime points and earned achievements intact.</p><p>Choose <b>Certificates</b> in the Staff menu. The Shop counter account also includes certificate previews, batch preparation and print records.</p></section><section class="card pad"><h2>St Peter’s merchandise collections</h2><p>Illustrative stationery, school spirit merchandise and REAL values stickers give students sets to collect. Collection progress follows items actually collected at the counter.</p><p>Items, artwork, prices and availability are examples for development.</p></section><section class="card pad"><h2>Celebrating the leaders</h2><p>Class leaderboards display the top 3 only. Year and overall leaderboards display up to the top 20. Lower ranks stay out of the public display.</p></section><section class="card pad"><h2>About this prototype</h2><p>All students and activity are fictional. Demo roles illustrate possible views, and changes stay in this browser. This is a demonstration for feedback before development and testing.</p><p>A working system would need school sign-in, verified family links, shared records and enforced permissions.</p></section></div>`}
function reset(){modal('Start the demo again?',`<p>This resets fictional points, prize collections and savings goals in this browser to their starting values.</p>`,'<button class="button outline" data-action="close">Keep exploring</button><button class="button danger" data-action="confirmReset">Reset demo data</button>')}
function teacherDashboard(){const date=localDate(),awards=data.awards.filter(a=>a.date===date),recent=data.awards.slice().sort((a,b)=>b.time-a.time).slice(0,5);return heading('Recognition that strengthens relationships.','Notice the positive, say why it matters and give students a success to build on.','<a class="button" href="'+SURVEY_URL+'" target="_blank" rel="noopener">Faculty and pastoral feedback</a>')+`<div class="hero teacher-dashboard-hero"><div class="hero-text"><div class="eyebrow">ST PETER’S · PROPOSAL</div><h2>Everyday contributions.<br>A positive connection with students.</h2><p>A quick record of personal praise, effort and progress. Recognise a class together or select individual students.</p><div class="teacher-title-actions"><button class="button" data-action="openClass" data-value="${state.cls}">Award lesson points</button><button class="button outline" data-action="nav" data-value="outside">Recognise out-of-class behaviour</button></div></div>${guardian(1)}</div>${stats([['users','Students recognised today',new Set(awards.map(a=>a.sid)).size,'In this fictional demo'],['bolt','Points awarded today',awards.reduce((n,a)=>n+a.amount,0),'Lessons and activities beyond lessons'],['star','Lesson stars today',awards.filter(a=>a.star).length,'Maximum two in each lesson']])}<div class="section-head"><h2>Teaching groups</h2><span class="sub">${data.students.length} fictional students · Years 7–10</span></div><div class="teacher-class-grid">${teachingGroups.map(g=>`<article class="card teacher-class-card"><div class="class-identity"><span>${parseInt(g.id)}</span><div><h3>${g.id}</h3><small>${g.subject} · Tutor group ${g.home}</small></div></div><p>${data.students.filter(s=>s.cls===g.home).length} students</p><button class="button" data-action="openClass" data-value="${g.id}">Open lesson</button></article>`).join('')}</div><div class="card pad mt"><h2>Recent recognition across participating groups</h2>${recent.map(a=>`<div class="activity-row"><span class="activity-icon">${icon(a.star?'star':'award')}</span><div><h4>${esc(student(a.sid).name)} · ${a.star?'Star of the Lesson':allReasons.find(c=>c.id===a.cat)?.name}</h4><small>${a.context==='outside'?esc(a.location):esc(a.subject)} · ${when(a.time)}</small></div><b class="delta">+${a.amount}</b></div>`).join('')}</div>`}
function navigate(page){state.page=page;state.search='';render();window.scrollTo({top:0,behavior:'instant'})}
function role(r){if(!navByRole[r])return;state.role=r;state.page=navByRole[r][0][0];history.replaceState(null,'','#'+r);state.selected.clear();state.search='';render();window.scrollTo({top:0,behavior:'instant'})}
function localDate(time=Date.now()){return new Date(time).toLocaleDateString('en-CA',{timeZone:'Pacific/Auckland'})}
function lessonGroup(){return teachingGroups.find(g=>g.id===state.cls)}
function rosterForLesson(){const g=lessonGroup();return g?data.students.filter(s=>s.cls===g.home):[]}
const families={morgan:{name:'Morgan family',parent:'Sam Morgan',children:['s48','s84']},singh:{name:'Singh family',parent:'Taylor Singh',children:['s72']}};
function option(value,label,current){return `<option value="${esc(value)}" ${String(value)===String(current)?'selected':''}>${esc(label)}</option>`}
function field(label,id,body){return `<div class="field"><label for="${id}">${label}</label>${body}</div>`}
function outside(){const q=state.outsideSearch.trim().toLowerCase(),matches=q?data.students.filter(s=>(s.name+' '+s.cls).toLowerCase().includes(q)):[],s=student(state.outsideStudent),recent=data.awards.filter(a=>a.context==='outside').slice().sort((a,b)=>b.time-a.time).slice(0,8);return heading('Positive moments beyond the classroom.','Search the school roster and recognise a distinct positive event. Up to 2 points per award.')+`<div class="grid2"><section class="card pad"><h2>Find the right student</h2><label for="outside-search">Student name or tutor group</label><input id="outside-search" class="full" type="search" data-input="outsideSearch" value="${esc(state.outsideSearch)}" placeholder="Try Alex Morgan or 9A" autocomplete="off"><p class="hint">All ${data.students.length} fictional students are searchable. Match both the name and tutor group.</p><div class="outside-results">${matches.map(x=>`<button class="student-result ${x.id===state.outsideStudent?'selected':''}" data-action="outsidePick" data-value="${x.id}">${avatar(x)}<span><b>${esc(x.name)}</b><small>Year ${x.year} · ${x.cls}</small></span>${x.id===state.outsideStudent?icon('check'):''}</button>`).join('')||`<p class="empty">${q?'No student matches. Try a first name or tutor group.':'Start typing to search across participating groups.'}</p>`}</div></section><section class="card pad"><h2>Recognition through our REAL values</h2><p class="hint">Respect, Engagement, Aspiration and Leadership. These example behaviours would be refined by a working party.</p>${s?`<div class="selected-student">${avatar(s)}<div><h3>${esc(s.name)}</h3><p>Year ${s.year} · ${s.cls}</p></div></div>`:'<p class="hint">Select a student from the search results.</p>'}<div class="form-stack">${field('Reason','outside-reason',`<select id="outside-reason" data-change="outsideReason">${schoolValues.map(value=>`<optgroup label="${value}">${outsideReasons.filter(r=>r.value===value).map(r=>option(r.id,value+' · '+r.name,state.outsideReason)).join('')}</optgroup>`).join('')}</select>`)}${field('Location','outside-location',`<select id="outside-location" data-change="outsideLocation">${['School grounds','Library','Dining hall','Corridor','School event','Other school setting'].map(l=>option(l,l,state.outsideLocation)).join('')}</select>`)}${field('Points','outside-amount',`<select id="outside-amount" data-change="outsideAmount">${option(1,'1 point',state.outsideAmount)}${option(2,'2 points (maximum)',state.outsideAmount)}</select>`)}${field('What did they do?','outside-note',`<textarea id="outside-note" data-input="outsideNote" maxlength="180" rows="3" placeholder="A short positive message for the student and family">${esc(state.outsideNote)}</textarea>`)}<button class="button full" data-action="outsideAward" ${s?'':'disabled'}>Award ${state.outsideAmount} positive point${state.outsideAmount==='1'?'':'s'}</button><p class="hint">Separate from lesson points. Record each distinct event once. The short message also appears in the family view.</p></div></section></div><section class="card pad mt"><h2>Recent out-of-class recognition</h2>${recent.map(a=>`<div class="activity-row"><span class="activity-icon">${icon('heart')}</span><div><h4>${esc(student(a.sid).name)} · ${student(a.sid).cls}</h4><p>${esc(a.note)}</p><small>${esc(a.location)} · ${when(a.time)} · ${esc(a.operator)}</small></div><b class="delta">+${a.amount}</b><button class="text-button" data-action="undoAward" data-value="${a.id}">Undo</button></div>`).join('')||'<p class="empty">No out-of-class positives yet.</p>'}</section>`}
function awardOutside(){if(!['teacher','admin'].includes(state.role))return toast('Use a staff demo account.');const s=student(state.outsideStudent),amount=Number(state.outsideAmount),note=state.outsideNote.trim();if(!s)return toast('Select a student first.');if(![1,2].includes(amount))return toast('An out-of-class award can be 1 or 2 points.');if(!note)return toast('Add a short positive message about this event.');if(note.length>180||!outsideReasons.some(c=>c.id===state.outsideReason))return toast('Check the award details.');const date=localDate();if(data.awards.some(a=>a.context==='outside'&&a.sid===s.id&&a.date===date&&a.note===note&&a.location===state.outsideLocation))return toast('That event has already been recognised today.');data.awards.push({id:uid(),sid:s.id,cat:state.outsideReason,value:outsideReasons.find(r=>r.id===state.outsideReason).value,amount,star:false,context:'outside',lesson:`outside|${date}|${uid()}`,subject:'Beyond lessons',date,period:'',location:state.outsideLocation,note,time:Date.now(),operator:state.role==='admin'?'Pastoral leader':'Gary Talbot'});save();state.outsideNote='';render();toast(`${s.name} received ${amount} point${amount===1?'':'s'} for their positive contribution.`)}
function scopedStudents(){return data.students.filter(s=>state.adminRole!=='pastoral'||s.year===Number(state.adminYear)).filter(s=>state.adminRole!=='department'||(s.demoSubjects||[]).includes(state.adminSubject)||teachingGroups.some(g=>g.subject===state.adminSubject&&g.home===s.cls)).filter(s=>state.filterYear==='all'||s.year===Number(state.filterYear))}
function analysisAwards(){const ids=new Set(scopedStudents().map(s=>s.id));return data.awards.filter(a=>ids.has(a.sid)&&(state.adminRole!=='department'||a.subject===state.adminSubject)&&(state.filterSubject==='all'||a.subject===state.filterSubject)&&(state.filterContext==='all'||a.context===state.filterContext)&&(!state.filterFrom||a.date>=state.filterFrom)&&(!state.filterTo||a.date<=state.filterTo))}
function analytics(){const awards=analysisAwards(),pool=scopedStudents(),recognised=new Set(awards.map(a=>a.sid)),points=awards.reduce((n,a)=>n+a.amount,0),subjects=[...new Set(teachingGroups.map(g=>g.subject)),'Beyond lessons'],scope=state.adminRole==='department'?state.adminSubject+' department':state.adminRole==='pastoral'?'Year '+state.adminYear+' pastoral':'Overall';const group=key=>{const m=new Map();awards.forEach(a=>{const k=key(a),x=m.get(k)||{name:k,count:0,points:0};x.count++;x.points+=a.amount;m.set(k,x)});return [...m.values()].sort((a,b)=>b.points-a.points)};const summary=(title,rows)=>`<section class="card pad"><h2>${title}</h2>${rows.length?`<table class="analysis-table"><thead><tr><th>Group</th><th>Awards</th><th>Points</th></tr></thead><tbody>${rows.map(r=>`<tr><th>${esc(r.name)}</th><td>${r.count}</td><td>${r.points}</td></tr>`).join('')}</tbody></table>`:'<p class="empty">No matching awards.</p>'}</section>`;const byStudent=pool.map(s=>{const aa=awards.filter(a=>a.sid===s.id);return {s,count:aa.length,points:aa.reduce((n,a)=>n+a.amount,0)}}).sort((a,b)=>b.points-a.points||a.s.name.localeCompare(b.s.name));return heading('Recognition within participating groups.','Explore who receives recognition, where it happens and how consistently the system is used.','<button class="button outline" data-action="exportAnalysis">Download filtered CSV</button>')+`<div class="card pad mb"><h2>Demo leader access</h2><div class="filters">${field('Leader role','admin-role',`<select id="admin-role" data-change="adminRole">${[['school','Programme leader'],['department','Head of department'],['pastoral','Pastoral leader']].map(([v,l])=>option(v,l,state.adminRole)).join('')}</select>`)}${state.adminRole==='department'?field('Department','admin-subject',`<select id="admin-subject" data-change="adminSubject">${subjects.filter(s=>s!=='Beyond lessons').map(s=>option(s,s,state.adminSubject)).join('')}</select>`):''}${state.adminRole==='pastoral'?field('Pastoral year group','admin-year',`<select id="admin-year" data-change="adminYear">${[7,8,9,10].map(y=>option(y,'Year '+y,state.adminYear)).join('')}</select>`):''}<span class="chip">${scope}</span></div><p class="hint">Six weeks of fictional records across Years 7–10, five subjects and all four REAL values. Live roles would come from verified school accounts.</p></div><div class="card pad mb"><div class="filters">${field('Year group','filter-year',`<select id="filter-year" data-change="filterYear">${option('all','All available years',state.filterYear)}${[7,8,9,10].map(y=>option(y,'Year '+y,state.filterYear)).join('')}</select>`)}${field('Subject','filter-subject',`<select id="filter-subject" data-change="filterSubject">${option('all','All available subjects',state.filterSubject)}${subjects.map(x=>option(x,x,state.filterSubject)).join('')}</select>`)}${field('Context','filter-context',`<select id="filter-context" data-change="filterContext">${[['all','All contexts'],['lesson','In lessons'],['outside','Out of class']].map(([v,l])=>option(v,l,state.filterContext)).join('')}</select>`)}${field('From','filter-from',`<input id="filter-from" type="date" data-change="filterFrom" value="${state.filterFrom}">`)}${field('To','filter-to',`<input id="filter-to" type="date" data-change="filterTo" value="${state.filterTo}">`)}</div></div>${state.filterFrom&&state.filterTo&&state.filterFrom>state.filterTo?'<p class="banner">The start date is after the end date. Change the date range.</p>':''}${stats([['bolt','Points recorded',points,awards.length+' award events'],['users','Students recognised',recognised.size+' / '+pool.length,(pool.length?Math.round(recognised.size/pool.length*100):0)+'% of selected cohort'],['star','Lesson stars',awards.filter(a=>a.star).length,'Within the selected filters']])}<p class="hint">Counts use recorded awards, excluding fictional starting balances. The sample includes different activity levels and students with few recorded positives so leaders can explore recognition patterns.</p><div class="settings-grid">${summary('Recognition by subject',group(a=>a.subject))}${summary('Recognition by reason',group(a=>a.star?'Star of the Lesson':allReasons.find(c=>c.id===a.cat)?.name||'Positive'))}${summary('Recognition by context',group(a=>a.context==='outside'?'Out of class':'In lessons'))}${summary('Staff recording activity',group(a=>a.operator))}</div><section class="card pad mt"><h2>Student recognition in this view</h2><p>${pool.length-recognised.size} students have no recorded award in the selected range. Use this to check opportunities for recognition.</p><div class="table-wrap"><table class="analysis-table"><thead><tr><th>Student</th><th>Tutor group</th><th>Awards</th><th>Points</th></tr></thead><tbody>${byStudent.map(x=>`<tr><th>${esc(x.s.name)}</th><td>${x.s.cls}</td><td>${x.count}</td><td>${x.points}</td></tr>`).join('')}</tbody></table></div></section>`}
function exportAnalysis(){if(state.role!=='admin')return;const rows=[['Date','Student','Tutor group','Subject','Context','Reason','Points','Staff'],...analysisAwards().map(a=>[a.date,student(a.sid).name,student(a.sid).cls,a.subject,a.context==='outside'?'Out of class':'Lesson',a.star?'Star of the Lesson':allReasons.find(c=>c.id===a.cat)?.name,a.amount,a.operator])];const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='School-Positives-Analysis.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function parentView(){const family=families[state.family],children=family.children.map(id=>student(id));if(!family.children.includes(state.parentChild))state.parentChild=family.children[0];const s=student(state.parentChild),level=recognition(s),badges=getBadges(s).filter(b=>b.count>=b.goal),awards=data.awards.filter(a=>a.sid===s.id),latest=awards.slice().sort((a,b)=>b.time-a.time)[0];return heading('Their positive moments, shared with you.',`Welcome, ${esc(family.parent)}. See recognition for your ${children.length===1?'child':'children'} across lessons and activities beyond lessons.`,field('Demo family','family-switch',`<select id="family-switch" data-change="family">${Object.entries(families).map(([id,f])=>option(id,f.name+' · '+f.children.length+' child'+(f.children.length===1?'':'ren'),state.family)).join('')}</select>`))+`<div class="family-children" aria-label="Your linked children">${children.map(c=>`<button class="child-card ${c.id===s.id?'active':''}" data-action="parentChild" data-value="${c.id}" aria-pressed="${c.id===s.id}">${avatar(c)}<span><b>${esc(c.name)}</b><small>Year ${c.year} · ${c.cls}</small></span></button>`).join('')}</div><div class="hero parent-hero"><div class="hero-text"><div class="eyebrow">${esc(s.name)} · ${s.cls}</div><h2>${level.name}</h2><p>${level.power} Recognition from every participating subject adds to this shared record.</p></div>${guardian(tierIndex(s))}</div>${stats([['award','Lifetime recognition',earned(s),'Points earned across participating groups'],['star','Achievements unlocked',badges.length,'Achievements recognise different contributions'],['heart','Latest positive',latest?when(latest.time):'None yet',latest?(latest.context==='outside'?'Beyond the classroom':latest.subject):'Positive moments will appear below']])}<div class="grid2"><section class="card pad"><h2>${esc(s.name.split(' ')[0])}’s positives</h2><p class="hint">Reasons, positive messages and the staff who recognised them.</p>${activity(s,Number.MAX_SAFE_INTEGER,true)}</section><section class="card pad"><h2>Achievements to celebrate</h2><div class="parent-badges">${badges.map(b=>`<div class="activity-row">${badgeToken(b)}<div><h3>${b.name}</h3><p>${b.desc}</p></div></div>`).join('')||'<p>New achievements will appear as positive contributions build.</p>'}</div><h3 class="mt">A shared picture of progress</h3><p>Lesson positives are worth 1 point. Star of the Lesson adds 2 extra, with up to two stars per lesson. Out-of-class awards are worth up to 2 points.</p><p class="hint">This view includes only this demo family’s linked children. It does not show other students, public rankings or internal leader analysis.</p></section></div>`}

document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,v=el.dataset.value;switch(action){case'certPreview':previewCertificates([v]);break;case'certBatch':previewCertificates(filteredCertificates().filter(r=>!r.record).map(r=>r.key));break;case'printCertificates':printCertificates();break;case'markCertificatesPrinted':markCertificatesPrinted();break;case'openClass':state.cls=v;state.selected.clear();navigate('classroom');break;case'nav':navigate(v);break;case'role':role(v);break;case'guide':navigate('guide');break;case'selectStudent':state.selected.has(v)?state.selected.delete(v):state.selected.add(v);render();break;case'selectAll':rosterForLesson().filter(s=>true&&s.name.toLowerCase().includes(state.search.toLowerCase())).forEach(s=>state.selected.add(s.id));render();break;case'clear':state.selected.clear();render();break;case'reason':state.reason=v;render();break;case'outsidePick':state.outsideStudent=v;render();break;case'outsideAward':awardOutside();break;case'parentChild':if(families[state.family].children.includes(v)){state.parentChild=v;render()}break;case'exportAnalysis':exportAnalysis();break;case'award':award();break;case'star':award(true);break;case'undoAward':{let a=data.awards.find(x=>x.id===v);if(!a)return;let s=student(a.sid);if(wallet(s)<a.amount)return toast('These points have been spent. Reverse the relevant shop collection first.');data.awards=data.awards.filter(x=>x.id!==v);save();render();toast('Award undone. Balance, lesson total and achievements recalculated.');break}case'goal':data.goals[state.student]=v;save();render();toast('Savings goal set. Visit the lunchtime school shop when you’re ready to collect.');break;case'badgeFilter':state.badgeFilter=v;render();break;case'rewardFilter':state.rewardFilter=v;render();break;case'league':state.league=v;render();break;case'counterProduct':state.shopProduct=v;render();break;case'shopPick':state.shopProduct=v;navigate('counter');break;case'prizeInfo':{let p=products.find(p=>p.id===v);modal(p.name,rewardArt(p)+`<p>${p.desc}</p><p><b>${p.price} points</b> · ${data.stock[p.id]} in stock<br>Illustrative merchandise. Items, prices and availability would be agreed before a trial.</p>`,'<button class="button" data-action="close">Done</button>');break}case'checkout':checkoutModal();break;case'confirmCheckout':confirmCheckout();break;case'refund':{let p=data.purchases.find(x=>x.id===v);if(!p)return;modal('Reverse this collection?',`<p>Return <b>${p.price} points</b> to <b>${esc(student(p.sid).name)}</b> and put one <b>${products.find(x=>x.id===p.pid).name}</b> back in stock. Please recover the physical prize too.</p>`,`<button class="button outline" data-action="close">Go back</button><button class="button" data-action="confirmRefund" data-value="${v}">Reverse collection</button>`);break}case'confirmRefund':{let p=data.purchases.find(x=>x.id===v);if(!p)return;data.stock[p.pid]++;data.purchases=data.purchases.filter(x=>x.id!==v);save();$('#dialog').close();render();toast('Collection reversed. Points returned and stock restored.');break}case'close':$('#dialog').close();break;case'reset':reset();break;case'confirmReset':data=seed();save();state.selected.clear();$('#dialog').close();render();toast('Demo reset. Ready for your presentation.');break}});
document.addEventListener('change',e=>{let k=e.target.dataset.change,v=e.target.value;if(!k)return;if(k==='family'){state.family=v;state.parentChild=families[v].children[0];}else if(k==='student'){state.student=v;state.leagueClass=student(v).cls;state.leagueYear=student(v).year;}else if(['cls','period','date'].includes(k)){if(k==='date'&&!v){e.target.value=state.date;return toast('A lesson needs a date.')}state[k]=v;state.selected.clear();}else if(k==='certYear'){state.certYear=v;state.certClass='all';}else if(k==='leagueYear')state[k]=Number(v);else state[k]=v;render()});
document.addEventListener('input',e=>{if(['outsideSearch','outsideNote','lessonNote'].includes(e.target.dataset.input)){const key=e.target.dataset.input,pos=e.target.selectionStart;state[key]=e.target.value;if(key==='outsideNote'||key==='lessonNote')return;render();const input=document.querySelector('[data-input="'+key+'"]');input.focus();input.setSelectionRange(pos,pos);return;}if(e.target.id==='cert-search'){const pos=e.target.selectionStart;state.certSearch=e.target.value;render();const input=$('#cert-search');input.focus();input.setSelectionRange(pos,pos);return;}if(e.target.dataset.input==='rosterSearch'){let start=e.target.selectionStart;state.search=e.target.value;render();let input=$('[data-input="rosterSearch"]');input.focus();try{input.setSelectionRange(start,start)}catch{}}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){let rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)e.target.close()}});
const initialRole=location.hash.slice(1);if(navByRole[initialRole]){state.role=initialRole;state.page=navByRole[initialRole][0][0];}
render();
